import{_ as t,o as a,c as o,a5 as n}from"./chunks/framework.Cooo9kuv.js";const P=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"标题":"923-批量旋转pdf指定页面-pdf页面旋转工具","日期":"2026-04-25T00:00:00.000Z","修改日期":"2026-05-27T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["PDF批量处理","PDF批量旋转","PDF旋转180度","PDF旋转90度","PDF旋转工具","PDF自定义角度","PDF角度调整","PDF页面旋转","办公PDF工具","批量旋转PDF"]},"headers":[],"relativePath":"md/PDF批处理/923-批量旋转pdf指定页面-pdf页面旋转工具.md","filePath":"md/PDF批处理/923-批量旋转pdf指定页面-pdf页面旋转工具.md"}'),s={name:"md/PDF批处理/923-批量旋转pdf指定页面-pdf页面旋转工具.md"};function p(e,r,g,h,l,i){return a(),o("div",null,[...r[0]||(r[0]=[n('<p>这个工具可以帮你批量旋转PDF文件的页面方向。不管是扫描件方向反了，还是从网上下载的PDF页面歪了，用它都能一键修正。</p><p>它支持同时处理一个或多个PDF文件，可以选择旋转全部页面或只旋转指定页面，还能保持原文件夹结构。界面简洁直观，拖进来就能用，省去你一个个打开PDF手动调整的麻烦。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-18.png" alt=""></p><h2 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h2><p><strong>批量处理</strong>：一次性处理文件夹中的所有PDF文件，不用一个一个来，省时省力。</p><p><strong>多种角度选择</strong>：提供预设角度按钮（-90°、90°、-180°、180°、-270°、270°），也支持自定义输入任意角度。</p><p><strong>指定页面旋转</strong>：可以只旋转PDF中的特定页面，比如输入”0,2,4”只旋转第1、3、5页，其他页面保持不变。</p><p><strong>保持文件夹结构</strong>：勾选后，输出文件会按照原文件夹的层级存放，方便你管理。</p><p><strong>穿透子文件夹</strong>：勾选后，程序会搜索所有子文件夹中的PDF文件，一并处理。</p><p><strong>实时进度显示</strong>：处理过程中显示当前正在处理哪个文件、进度百分比，一目了然。</p><h2 id="设置旋转选项" tabindex="-1"><strong>设置旋转选项</strong> <a class="header-anchor" href="#设置旋转选项" aria-label="Permalink to &quot;**设置旋转选项**&quot;">​</a></h2><ul><li>选择预设角度（90°、180°、270°等）</li><li>或在自定义框中输入任意角度（-360°~360°）</li><li>可选：指定要旋转的页面（如：0,2,4 或 1-5）</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>程序会覆盖同名文件，如需保留原文件请设置不同的输出目录</li><li>穿透子文件夹选项会递归处理所有子文件夹中的PDF</li></ul><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><h3 id="操作1-旋转单个pdf文件" tabindex="-1">操作1：旋转单个PDF文件 <a class="header-anchor" href="#操作1-旋转单个pdf文件" aria-label="Permalink to &quot;操作1：旋转单个PDF文件&quot;">​</a></h3><p><strong>第一步</strong>：点击<strong>浏览按钮</strong>，在弹出的对话框中选择要处理的PDF文件，然后点击确定。</p><p><strong>第二步</strong>：在旋转角度区域，选择你需要的角度。可以用鼠标点击预设角度按钮（-90°、90°等），也可以在自定义输入框中输入任意角度值。</p><p><strong>第三步</strong>：点击<strong>开始处理按钮</strong>，程序开始处理。</p><p><strong>第四步</strong>：处理完成后，去你设置的输出文件夹拿结果。</p><p>示例：你的<em>项目报告.pdf</em>扫描歪了，需要顺时针旋转90度。选择该文件，点击90°按钮，点开始处理，处理后的文件就在输出目录里了。</p><hr><h3 id="操作2-批量旋转文件夹中的所有pdf" tabindex="-1">操作2：批量旋转文件夹中的所有PDF <a class="header-anchor" href="#操作2-批量旋转文件夹中的所有pdf" aria-label="Permalink to &quot;操作2：批量旋转文件夹中的所有PDF&quot;">​</a></h3><p><strong>第一步</strong>：点击<strong>浏览按钮</strong>，选择包含多个PDF文件的文件夹。</p><p><strong>第二步</strong>：根据需要勾选<strong>穿透子文件夹</strong>，如果文件夹里有子文件夹且子文件夹里的PDF也要处理，就勾选这个选项。</p><p><strong>第三步</strong>：根据需要勾选<strong>保持原文件夹结构</strong>，如果希望输出文件按原文件夹层级存放，就勾选此项。</p><p><strong>第四步</strong>：选择旋转角度，然后点击<strong>开始处理按钮</strong>。</p><p><strong>第五步</strong>：等待处理完成，在日志区域查看处理结果，最后去输出文件夹获取所有处理好的文件。</p><p>示例：你有一个<em>资料</em>文件夹，里面有10个子文件夹，每个子文件夹里都有PDF文件需要旋转90度。勾选穿透子文件夹和保持原文件夹结构，点开始处理，所有文件都会按原结构旋转后保存到新位置。</p><hr><h3 id="操作3-只旋转pdf中的指定页面" tabindex="-1">操作3：只旋转PDF中的指定页面 <a class="header-anchor" href="#操作3-只旋转pdf中的指定页面" aria-label="Permalink to &quot;操作3：只旋转PDF中的指定页面&quot;">​</a></h3><p><strong>第一步</strong>：选择要处理的PDF文件或文件夹。</p><p><strong>第二步</strong>：在”指定页面”输入框中输入你要旋转的页码。页码从1开始，与平时数页码的习惯一致。</p><p><strong>第三步</strong>：输入格式可以是单个页码（如”1”表示第1页）、多个页码用逗号分隔（如”0,2,4”表示第1、3、5页）、或范围格式（如”1-5”表示第1到5页）。</p><p><strong>第四步</strong>：选择旋转角度，点击<strong>开始处理按钮</strong>。</p><p>示例：你的<em>会议记录.pdf</em>有10页，只有第3页和第7页是歪的。在指定页面输入框输入”3,7”，选择90°，点开始处理。只有第3页和第7页会被旋转，其他页面保持原样。</p><h3 id="数据存储位置" tabindex="-1">数据存储位置 <a class="header-anchor" href="#数据存储位置" aria-label="Permalink to &quot;数据存储位置&quot;">​</a></h3><p><strong>输入文件</strong>：原始PDF文件不会被修改，所有处理都在输出目录生成新文件。</p><p><strong>输出文件</strong>：保存在你设置的输出文件夹路径，默认为原文件所在目录下的<em>rotated</em>文件夹。</p><p><strong>程序本身</strong>：程序是绿色软件，不需要安装，下载后直接双击运行。</p><h3 id="注意事项-1" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-1" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>处理前请备份重要数据，防止误操作导致文件丢失。虽然程序只生成新文件不修改原文件，但建议重要文件还是先备份。</p><p>操作过程中<strong>不要关闭程序窗口</strong>，等待处理完成提示出现。如果提前关闭，可能导致部分文件处理不完整。</p><p>确认目标文件夹有<strong>足够空间</strong>存放处理结果。PDF文件可能较大，批量处理时需要预留足够磁盘空间。</p><p>首次使用建议<strong>先用少量文件测试</strong>，确认效果后再批量处理。这样可以避免大量文件处理后发现效果不理想。</p><p>如果程序无响应，耐心等待片刻。大文件处理可能需要较长时间，程序实际上在后台运行中。</p><p>程序会<strong>跳过正在写入的文件</strong>（如被其他程序打开的PDF），处理完后可在日志中查看失败文件的数量和原因。</p><h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p><strong>Q: PDF批量旋转工具哪个好用？</strong><br> A: 推荐使用这个PDF批量旋转工具，支持自定义角度、页面选择、拖拽操作。只需选择文件，设置角度，点击开始，批量处理瞬间完成。</p><p><strong>Q: 可以只旋转PDF的某些页面吗？</strong><br> A: 可以！在”指定页面”框中输入页面编号，如”0,2,4”表示第1、3、5页，或”1-5”表示第1到5页。<strong>留空则旋转所有页面。</strong></p><p><strong>Q: 会覆盖原文件吗？</strong><br> **A: 默认会在输出目录生成新文件，不会覆盖原文件。**如果输出目录与源文件相同，会自动添加”_rotated”后缀以区分。</p><p><strong>Q: 支持子文件夹中的PDF吗？</strong><br> A: 支持！勾选”穿透子文件夹”选项后，程序会递归处理所有子文件夹中的PDF，并保持原文件夹结构。</p><p><strong>Q: 支持什么旋转角度？</strong><br> A: 支持预设角度（-90°、90°、-180°、180°、-270°、270°），也支持在自定义框中输入任意角度（-360°~360°）。</p><h3 id="问题-为什么处理后的pdf大小变大了" tabindex="-1">问题：为什么处理后的PDF大小变大了？ <a class="header-anchor" href="#问题-为什么处理后的pdf大小变大了" aria-label="Permalink to &quot;问题：为什么处理后的PDF大小变大了？&quot;">​</a></h3><p>答案：这是正常现象。程序使用PyMuPDF库处理PDF，该库在保存时会进行内部优化重建，可能会改变文件编码方式导致大小变化。但文档内容和旋转效果完全正确，页面方向已被正确旋转。</p><hr><h3 id="问题-指定页面的输入格式是怎样的" tabindex="-1">问题：指定页面的输入格式是怎样的？ <a class="header-anchor" href="#问题-指定页面的输入格式是怎样的" aria-label="Permalink to &quot;问题：指定页面的输入格式是怎样的？&quot;">​</a></h3><p>答案：支持三种格式。<strong>单个页码</strong>：直接输入数字，如”3”表示第3页。<strong>多个页码</strong>：用英文逗号分隔，如”1,3,5”表示第1、3、5页。<strong>范围格式</strong>：用减号连接起止页码，如”1-5”表示第1到5页。也可以混合使用，如”1,3,5-8”表示第1、3、5到8页。页码从1开始计数，不是从0开始。</p><hr><h3 id="问题-如何只旋转pdf而不改变其他内容" tabindex="-1">问题：如何只旋转PDF而不改变其他内容？ <a class="header-anchor" href="#问题-如何只旋转pdf而不改变其他内容" aria-label="Permalink to &quot;问题：如何只旋转PDF而不改变其他内容？&quot;">​</a></h3><p>答案：程序只修改PDF页面的旋转角度，不会改变文档内容、排版、图片质量等。处理后的PDF文字、图片、排版都与原文件完全一致，只是页面方向被调整了。</p><hr><h3 id="问题-处理过程中可以停止吗" tabindex="-1">问题：处理过程中可以停止吗？ <a class="header-anchor" href="#问题-处理过程中可以停止吗" aria-label="Permalink to &quot;问题：处理过程中可以停止吗？&quot;">​</a></h3><p>答案：不建议，建议先测试再批量使用。</p><h1 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h1><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位windows操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p>**3、程序如何安装：**不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h1 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h1><p><strong>解压后直接使用即可，不需要安装，程序可以放在任意位置</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-44.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2738.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2738.html</a></p>',76)])])}const c=t(s,[["render",p]]);export{P as __pageData,c as default};
